    assert admin_initial['items']>20 and not admin_initial['hidden'] and not admin_initial['guidance'] and 300<=admin_initial['clientHeight']<=380 and admin_initial['scrollHeight']>admin_initial['clientHeight'] and admin_initial['overflowY'] in ['auto','scroll'],admin_initial
    before=script("return [...document.querySelectorAll('#invitation-chapter-results .chapter-picker-item')].slice(0,10).map(row=>({text:row.innerText,html:row.innerHTML,value:row.querySelector('input')?.value,strong:row.querySelector('strong')?.textContent,small:row.querySelector('small')?.textContent}));")
    admin_geometry=script("const container=document.querySelector('#invitation-chapter-results'),rows=[...container.querySelectorAll('.chapter-picker-item')].slice(0,10),pick=node=>{const s=getComputedStyle(node),r=node.getBoundingClientRect();return {display:s.display,width:s.width,gap:s.gap,margin:s.margin,padding:s.padding,borderBottom:s.borderBottom,whiteSpace:s.whiteSpace,alignItems:s.alignItems,fontFamily:s.fontFamily,fontSize:s.fontSize,fontWeight:s.fontWeight,top:r.top,bottom:r.bottom,height:r.height,left:r.left,right:r.right}};return {container:pick(container),rows:rows.map(row=>({...pick(row),radio:pick(row.querySelector('input')),strong:pick(row.querySelector('strong')),small:pick(row.querySelector('small'))})),overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth};")
    chapters=async_script("const done=arguments[arguments.length-1];fetch('/api/auth/chapters.php').then(async r=>done({status:r.status,data:await r.json()}));")
    king=next((item for item in chapters['data']['chapters'] if 'Königsforst' in str(item.get('chapterName',''))),None)
    assets=async_script("const done=arguments[arguments.length-1],scripts=[...document.scripts].map(x=>x.src),app=scripts.find(x=>x.includes('/assets/app.js'))||'',picker=scripts.find(x=>x.includes('/assets/chapter-picker.js'))||'';Promise.all([fetch(app,{cache:'no-store'}).then(r=>r.text()),fetch(picker,{cache:'no-store'}).then(r=>r.text())]).then(([appText,pickerText])=>done({app,picker,componentLoaded:typeof window.CrossChappChapterPicker?.create==='function',oldInvitationRenderer:appText.includes('renderInvitationChapters'),hasFallback:pickerText.includes(\"chapterName || 'Chapter'\")||pickerText.includes(\"chapterName ?? 'Chapter'\"),hasFilter:pickerText.includes(\"typeof item.chapterName === 'string'\"),hasPostal:pickerText.includes('item.postalCode, item.city, item.region')}));")
    network=initial_network+request('POST',f'/session/{session}/log',{'type':'performance'});messages=[json.loads(entry['message'])['message'] for entry in network];panel_urls=[item['params']['request']['url'] for item in messages if item['method']=='Network.requestWillBeSent' and ('/api/auth/chapters.php' in item['params']['request']['url'] or '/api/admin/invitations.php' in item['params']['request']['url'])]
    cologne=script("const input=document.querySelector('#invitation-search');input.value='Köln';input.dispatchEvent(new Event('input',{bubbles:true}));return [...document.querySelectorAll('#invitation-chapter-results .chapter-picker-item')].slice(0,10).map(row=>({strong:row.querySelector('strong')?.textContent,small:row.querySelector('small')?.textContent,text:row.innerText}));")
    search=script("const input=document.querySelector('#invitation-search');input.value='Königsforst';input.dispatchEvent(new Event('input',{bubbles:true}));const row=document.querySelector('#invitation-chapter-results .chapter-picker-item'),result=row?{text:row.innerText,html:row.innerHTML,value:row.querySelector('input').value,strong:row.querySelector('strong').textContent,small:row.querySelector('small').textContent}:null;row?.querySelector('input').click();return result?{...result,selected:document.querySelector('#invitation-selected-chapter').textContent,checked:row.querySelector('input').checked,listVisible:!document.querySelector('#invitation-chapter-results').hidden}:null;")
    assert chapters['status']==200 and king=={'orgId':44628,'chapterName':'Königsforst BNI (Overath)','city':'Rösrath-Forsbach','postalCode':'51503','region':'Bergisches Land','countryCode':'DE'},king
